DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_THEKINGDOMS' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_THEKINGDOMS_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_1','The Kingdoms[NEWLINE]Political stability, controlled expansion and named guards[NEWLINE]Flexible; Science/Culture from stability or supported Domination[NEWLINE][NEWLINE]Keep local Houses and the succession manageable while building a conventional empire. The Crown''s military and economic plans work best when it can meet reasonable demands without empowering every claimant indiscriminately.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_2','Develop food, Gold and defensible cities before adding more political obligations. Read House personalities and loyalty. Walls provide useful stability support; retain money for demands rather than committing the whole treasury to expansion.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_3','Resolve demands using their actual current requirements. Evaluate Estates, Charters and authority choices for their costs and political consequences. Appoint King''s Guards deliberately and preserve the useful identities already serving the realm.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_4','Enter succession with stable institutions and a viable treasury. If civil war occurs, choose backing consciously and protect the economy through its penalties. Resume a normal victory programme after reunification rather than accepting permanent crisis management.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_5','- Stable institutions and local Walls support a durable realm.[NEWLINE]- Named Guards reward careful appointments and veteran preservation.[NEWLINE]- House management gives several levers for solving political problems.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_6','- Low Stability can turn succession into a costly civil war.[NEWLINE]- Demands and appeasement compete with construction, Gold and military priorities.[NEWLINE]- Supporting powerful personalities can create later political liabilities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_7','- Apply economic and military pressure when demands or succession are already stretching the realm.[NEWLINE]- Threaten several important cities so Guards and garrisons cannot solve every problem.[NEWLINE]- Avoid assuming a civil war creates a new ordinary rival civilization; exploit its actual internal penalties.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_8','- Ignoring a feasible demand until its expiry penalty arrives.[NEWLINE]- Treating a claimant score as a guaranteed succession probability.[NEWLINE]- Expanding or campaigning without money and stability for the next political cycle.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A stable realm with Walls and prepared defenders can make the limited potion window harder to convert into city losses.[NEWLINE][NEWLINE]McPvP: Maintained border defenses and named military support can contest objective units near city approaches.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Reduced economic output makes funding demands and maintaining a stable home front harder.[NEWLINE][NEWLINE]Viltrum: Sustained first-conquest pressure can overwhelm a realm already paying for political cohesion.');
