INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_THEKINGDOMS_LEADER_DESCRIPTION',Text FROM Language_en_US WHERE Tag='TXT_KEY_KINGDOMS_LEADER';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_BACKGROUND','Keep local Houses and the succession manageable while building a conventional empire. The Crown''s military and economic plans work best when it can meet reasonable demands without empowering every claimant indiscriminately.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_THEKINGDOMS_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_KINGDOMS_CIV_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_LEADER_BACKGROUND','Keep local Houses and the succession manageable while building a conventional empire. The Crown''s military and economic plans work best when it can meet reasonable demands without empowering every claimant indiscriminately.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_THEKINGDOMS_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_KINGDOMS_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_STRATEGY','Keep local Houses and the succession manageable while building a conventional empire. The Crown''s military and economic plans work best when it can meet reasonable demands without empowering every claimant indiscriminately.[NEWLINE][NEWLINE]Develop food, Gold and defensible cities before adding more political obligations. Read House personalities and loyalty. Walls provide useful stability support; retain money for demands rather than committing the whole treasury to expansion.[NEWLINE][NEWLINE]Resolve demands using their actual current requirements. Evaluate Estates, Charters and authority choices for their costs and political consequences. Appoint King''s Guards deliberately and preserve the useful identities already serving the realm.[NEWLINE][NEWLINE]Enter succession with stable institutions and a viable treasury. If civil war occurs, choose backing consciously and protect the economy through its penalties. Resume a normal victory programme after reunification rather than accepting permanent crisis management.');
