INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_LEADER_TEXT_2','Develop food, Gold and defensible cities before adding more political obligations. Read House personalities and loyalty. Walls provide useful stability support; retain money for demands rather than committing the whole treasury to expansion.[NEWLINE][NEWLINE]Resolve demands using their actual current requirements. Evaluate Estates, Charters and authority choices for their costs and political consequences. Appoint King''s Guards deliberately and preserve the useful identities already serving the realm.[NEWLINE][NEWLINE]Enter succession with stable institutions and a viable treasury. If civil war occurs, choose backing consciously and protect the economy through its penalties. Resume a normal victory programme after reunification rather than accepting permanent crisis management.');
