INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THEKINGDOMS_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A stable realm with Walls and prepared defenders can make the limited potion window harder to convert into city losses.[NEWLINE][NEWLINE]McPvP: Maintained border defenses and named military support can contest objective units near city approaches.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Reduced economic output makes funding demands and maintaining a stable home front harder.[NEWLINE][NEWLINE]Viltrum: Sustained first-conquest pressure can overwhelm a realm already paying for political cohesion.');
